(() => {
 'use strict';const RI=window.RI,esc=RI.esc;
 RI.mountWorkspaceSwitcher=(root,id)=>{
  if(!['resume','links','themes','studio','publish'].includes(id))return;
  const host=document.createElement('div');host.className='workspace-picker';host.innerHTML='<label for="active-workspace">صفحهٔ در حال ویرایش</label><select class="select" id="active-workspace">'+[[1,'زیردامنهٔ اول · رزومه و لینک'],[2,'زیردامنهٔ دوم · رزومه و لینک'],[3,'آدرس مسیری · فقط لینک'],...(RI.ownerSettings?.extraSubdomain?[[4,'زیردامنهٔ سوم · رزومه و لینک']]:[])].map(([slot,label])=>'<option value="'+slot+'" '+(RI.workspaceSlot===slot?'selected':'')+'>'+label+(!RI.canWorkspace(slot)?' · قفل':'')+'</option>').join('')+'</select><span>'+(RI.workspaceSlot===3?'فقط لینک':'زیردامنهٔ مستقل')+'</span>';
  root.querySelector('.page-head')?.after(host);
  if(!host.querySelector('option[value="'+RI.workspaceSlot+'"]')){const option=document.createElement('option');option.value=RI.workspaceSlot;option.textContent='زیردامنهٔ '+RI.fa(RI.workspaceSlot-1);host.querySelector('select').append(option);host.querySelector('select').value=String(RI.workspaceSlot);}
  host.querySelector('select').addEventListener('change',async event=>{const slot=Number(event.target.value);if(slot===RI.workspaceSlot)return;if(!RI.canWorkspace(slot)){event.target.value=RI.workspaceSlot;RI.toast('این جایگاه به اشتراک یا سهمیهٔ اضافه نیاز دارد',{kind:'info'});return;}if(!await RI.leaveGuard()){event.target.value=RI.workspaceSlot;return;}try{sessionStorage.setItem('ri-workspace',String(slot));}catch{RI.toast('انتخاب صفحه ذخیره نشد',{kind:'error'});return;}RI.advisorClear?.();location.assign('/dashboard/'+(slot===3?'links':id==='publish'?'publish':id==='themes'?'themes':'resume')+'/?workspace='+slot);});
  const fetchOptions=async(cursor=0)=>{try{const result=await RI.dashboardRequest('workspaces?cursor='+cursor);if(!host.isConnected)return;for(const row of result.rows){let option=host.querySelector('option[value="'+row.slot+'"]');if(!option){option=document.createElement('option');option.value=row.slot;host.querySelector('select').append(option);}const label=row.slot===3?'آدرس مسیری · فقط لینک':'زیردامنهٔ '+RI.fa(row.slot<3?row.slot:row.slot-1)+' · رزومه و لینک';option.textContent=label+(row.slug?' · '+row.slug:'')+(row.locked?' · قفل':'');}host.querySelector('select').value=String(RI.workspaceSlot);host.querySelector('[data-more-workspaces]')?.remove();if(result.nextCursor!==null&&result.nextCursor!==undefined){const more=document.createElement('button');more.className='btn btn--soft';more.type='button';more.dataset.moreWorkspaces='';more.textContent='صفحه‌های بیشتر';more.onclick=()=>{more.disabled=true;fetchOptions(result.nextCursor);};host.append(more);}}catch{host.querySelector('[data-more-workspaces]')?.remove();RI.toast('فهرست صفحه‌ها دریافت نشد؛ صفحه را تازه کن',{kind:'info'});}};fetchOptions();
  if(RI.workspaceSlot===3){document.querySelector('#sidebar [data-route=resume]')?.setAttribute('hidden','');if(id==='resume')RI.go('links');}
 };
 RI.activitySummary=(items,values)=>'<div class="activity-summary">'+items.map(([id,label,icon])=>'<article class="activity-card"><span class="activity-card__icon">'+RI.icon(icon)+'</span><div><span>'+esc(label)+'</span><strong>'+(values?RI.fa(values[id]||0):'—')+'</strong></div></article>').join('')+'</div>';
 RI.openPublication=()=>{
  if(!RI.canWorkspace(RI.workspaceSlot)){RI.toast('این جایگاه به اشتراک یا سهمیهٔ اضافه نیاز دارد؛ محتوایت حفظ شده است',{kind:'info'});RI.go('billing');return;}
  const ready=RI.readiness();let busy=false;
  const modal=RI.modal({title:'انتشار صفحه‌ها',body:'<p>انتشار، آخرین تغییرات ذخیره‌شده را برای همه قابل مشاهده می‌کند.</p><div class="publish-picker">'+RI.pageKinds().map(kind=>{const missing=ready[kind].filter(x=>x.req&&!x.done),live=RI.state.pub[kind].status==='published';return '<section><div><b>'+RI.icon(kind==='resume'?'resume':'link')+(kind==='resume'?'رزومه':'صفحهٔ لینک‌ها')+'</b><small>'+(missing.length?RI.fa(missing.length)+' پایه نیاز به تکمیل دارد':live?'نسخهٔ عمومی موجود است':'آمادهٔ اولین انتشار')+'</small></div>'+(missing.length?'<a class="btn btn--soft" href="/dashboard/studio/" data-go="studio" data-publish-fix>تکمیل</a>':'<button type="button" class="btn btn--primary" data-publish-kind="'+kind+'">'+(live?'به‌روزرسانی':'انتشار')+'</button>')+'</section>';}).join('')+'</div><p role="status" data-publish-status></p>',actions:[{label:'بستن',kind:'ghost'}]});
  modal.body.querySelectorAll('[data-publish-fix]').forEach(a=>a.addEventListener('click',()=>modal.close()));
  modal.body.querySelectorAll('[data-publish-kind]').forEach(button=>button.addEventListener('click',async()=>{
   if(busy)return;busy=true;const buttons=[...modal.body.querySelectorAll('[data-publish-kind]')],status=modal.body.querySelector('[data-publish-status]');buttons.forEach(b=>b.disabled=true);
   try{if((RI.state.ui.dirty||RI.state.ui.saving)&&!(await RI.save()))throw new Error('ابتدا خطای ذخیره را برطرف کن؛ اطلاعات فرم حفظ شده است.');await RI.publish(button.dataset.publishKind,(i,steps)=>{status.textContent=steps[i]||'انتشار انجام شد';});button.textContent='منتشر شد';button.dataset.published='true';RI.toast('نسخهٔ عمومی منتشر شد');}
   catch(error){status.textContent=error.message==='account-incomplete'?'مشخصات حساب را در تنظیمات کامل کن.':error.message;RI.toast(status.textContent,{kind:'error'});}
   finally{busy=false;buttons.forEach(b=>b.disabled=b.dataset.published==='true');}
  }));
 };
 const disclosureAnimations=new WeakMap();
 document.addEventListener('click',event=>{
  const summary=event.target.closest('summary'),details=summary?.parentElement;if(!details?.matches('#view details')||event.target.closest('a,button,input')||event.defaultPrevented)return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  event.preventDefault();const prior=disclosureAnimations.get(details),opening=prior?!prior.opening:!details.open,start=details.getBoundingClientRect().height;
  prior?.animation.cancel();details.style.height='';details.style.overflow='hidden';details.open=true;
  const end=opening?details.getBoundingClientRect().height:summary.getBoundingClientRect().height+parseFloat(getComputedStyle(details).paddingTop)+parseFloat(getComputedStyle(details).paddingBottom)+2;
  const animation=details.animate({height:[start+'px',end+'px']},{duration:opening?260:190,easing:'cubic-bezier(.16,1,.3,1)'});disclosureAnimations.set(details,{animation,opening});
  animation.onfinish=()=>{details.open=opening;details.style.height='';details.style.overflow='';disclosureAnimations.delete(details);};
 });
 RI.searchText=value=>String(value||'').normalize('NFKC').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).toLowerCase();
 RI.matches=(query,...values)=>{const text=RI.searchText(values.join(' '));return RI.searchText(query).trim().split(/\s+/).every(term=>text.includes(term));};
 RI.tabsHtml=(items,selected,attribute='workspaceTab')=>'<div class="tabs workspace-tabs" role="tablist">'+items.map(([id,label])=>'<button type="button" role="tab" data-'+attribute.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+'="'+id+'" aria-selected="'+(id===selected)+'">'+label+'</button>').join('')+'</div>';
 RI.historyFilters=(q='',status='',statuses=[],from='',to='')=>'<div class="workspace-tools"><div class="field"><label class="field__label" for="history-q">جست‌وجو</label><input class="input" id="history-q" type="search" value="'+esc(q)+'" placeholder="شرح، شناسه یا مبلغ"></div>'+(statuses.length?'<div class="field"><label class="field__label" for="history-status">وضعیت</label><select class="select" id="history-status"><option value="">همه</option>'+statuses.map(([id,label])=>'<option value="'+id+'" '+(id===status?'selected':'')+'>'+label+'</option>').join('')+'</select></div>':'')+'<div class="field"><label class="field__label" for="history-from">از تاریخ</label><input class="input" type="date" id="history-from" value="'+esc(from)+'"></div><div class="field"><label class="field__label" for="history-to">تا تاریخ</label><input class="input" type="date" id="history-to" value="'+esc(to)+'"></div></div>';
 RI.historyRows=(rows,filter)=>rows.filter(r=>RI.matches(filter.q,r.label,r.title,r.name,r.id,r.rrn,r.trace,r.amount,r.price)&&(!filter.status||r.status===filter.status||r.kind===filter.status)&&(!filter.from||r.at>=new Date(filter.from).getTime())&&(!filter.to||r.at<new Date(filter.to).getTime()+86400000));
 RI.pagination=(page,total,size=20)=>'<nav class="pagination" aria-label="صفحه‌های نتایج"><button type="button" class="btn btn--soft btn--sm" data-page="'+(page-1)+'" '+(page<=1?'disabled':'')+'>'+RI.icon('chevR')+'قبلی</button><span role="status">'+RI.fa(total)+' نتیجه · صفحهٔ '+RI.fa(page)+' از '+RI.fa(Math.max(1,Math.ceil(total/size)))+'</span><button type="button" class="btn btn--soft btn--sm" data-page="'+(page+1)+'" '+(page*size>=total?'disabled':'')+'>بعدی'+RI.icon('chevL')+'</button></nav>';
 RI.paymentStatuses={creating:'آماده‌سازی',pending:'تأیید نشده',verifying:'در حال تأیید بانک',paid:'شارژ انجام شد',failed:'اتصال ناموفق',review:'نیاز به بررسی',reversed:'برگشت به کارت',cancelled:'انصراف',expired:'پایان مهلت'};
 RI.mountHistory=(host,type)=>{
  let alive=true,page=1,timer,serial=0;const filter={q:'',status:'',from:'',to:''};
  host.innerHTML=RI.historyFilters('','',type==='bank'?Object.entries(RI.paymentStatuses):type==='ledger'?[['in','واریز اعتبار'],['out','خرید و برداشت']]:[])+'<div data-history-results aria-live="polite"></div>';
  const results=host.querySelector('[data-history-results]');
  async function load(){const loadId=++serial;results.setAttribute('aria-busy','true');try{const data=await RI.dashboardRequest('history?'+new URLSearchParams({type,page,...filter}));if(!alive||loadId!==serial)return;results.innerHTML=data.rows.length?data.rows.map(row=>'<article class="history-row"><span class="row__ico">'+RI.icon(type==='bank'?'card':type==='purchases'?'gift':row.amount>0?'down':'up')+'</span><div><b>'+(type==='bank'?RI.toman(row.amount)+' · '+RI.fa(row.it)+' It':esc(row.label))+'</b><p>'+RI.date(row.at)+(type==='bank'?' · '+esc(RI.paymentStatuses[row.status]||row.status)+' · '+(row.provider==='sep'?'سپ':'زیبال'):' · '+(type==='purchases'?RI.it(row.price):'موجودی پس از تراکنش: '+RI.fa(row.balance)+' It'))+'</p><small class="ltr-inline">'+esc(row.rrn||row.id)+'</small></div>'+(type==='bank'?'<div class="btnrow"><a class="btn btn--soft btn--sm" href="/payments/result?id='+row.id+'">فاکتور و وضعیت</a></div>':'<strong class="ltr-inline">'+(row.amount>0?'+':'')+RI.fa(row.amount)+' It</strong>')+'</article>').join('')+RI.pagination(page,data.total):RI.empty({icon:'receipt',title:'نتیجه‌ای برای این فیلتر نیست'});}catch(e){if(alive&&loadId===serial)results.innerHTML='<p role="alert">'+esc(e.message)+'</p><button class="btn btn--soft" type="button" data-history-retry>تلاش دوباره</button>';}finally{if(alive&&loadId===serial)results.setAttribute('aria-busy','false');}}
  const update=e=>{const key={ 'history-q':'q','history-status':'status','history-from':'from','history-to':'to'}[e.target.id];if(!key)return;filter[key]=e.target.value;page=1;clearTimeout(timer);timer=setTimeout(load,key==='q'?300:0);};host.addEventListener('input',update);host.addEventListener('change',update);
  RI.delegate(host,'click','[data-page]',(e,b)=>{page=Number(b.dataset.page);load();});RI.delegate(host,'click','[data-history-retry]',load);load();return()=>{alive=false;clearTimeout(timer);};
 };
 RI.brandingHtml=kind=>{const value=RI.C().branding?.[kind]||{mode:'resumeit',text:''};return '<section class="branding-controls"><h3>امضای پایین صفحه</h3><div class="segmented" role="group" aria-label="نشان پایین صفحه">'+[['resumeit','رزومیت'],['custom','امضای خودت'],['hidden','بدون نشان']].map(([id,label])=>'<button type="button" data-brand-mode="'+id+'" data-brand-kind="'+kind+'" aria-pressed="'+(value.mode===id)+'">'+label+(id!=='resumeit'&&!RI.hasSub()?' '+RI.icon('lock'):'')+'</button>').join('')+'</div>'+(value.mode==='custom'?'<div class="field"><label class="field__label" for="custom-brand">متن امضای تو</label><input class="input" id="custom-brand" data-brand-text="'+kind+'" maxlength="100" value="'+esc(value.text)+'"></div>':'')+'</section>';};
 RI.bindBranding=root=>{
  RI.delegate(root,'click','[data-brand-mode]',(e,b)=>{if(b.dataset.brandMode!=='resumeit'&&!RI.hasSub()){RI.toast('امضای اختصاصی و حذف نشان با اشتراک فعال در دسترس است',{kind:'info'});RI.go('billing');return;}const kind=b.dataset.brandKind;RI.C().branding[kind].mode=b.dataset.brandMode;RI.touch('branding');b.closest('.branding-controls').outerHTML=RI.brandingHtml(kind);root.querySelector('[data-brand-text="'+kind+'"]')?.focus();});
  root.addEventListener('input',e=>{if(e.target.dataset.brandText){RI.C().branding[e.target.dataset.brandText].text=e.target.value;RI.touch('branding');}});
 };
 RI.completionStrip=kind=>{const list=RI.readiness()[kind],missing=list.filter(x=>x.req&&!x.done);return '<div class="completion-strip" data-ready-kind="'+kind+'"><div class="completion-strip__summary" role="status">'+RI.icon(missing.length?'edit':'check')+'<span>'+(missing.length?'برای انتشار، '+RI.fa(missing.length)+' قدم باقی مانده':RI.canWorkspace(RI.workspaceSlot)?'این صفحه آمادهٔ انتشار است':'محتوا کامل است؛ دسترسی انتشار این جایگاه را بررسی کن')+'</span><a href="/dashboard/studio/" data-go="studio">مرور آمادگی</a><span class="chip">'+RI.fa(list.filter(x=>x.done).length)+' / '+RI.fa(list.length)+'</span></div>'+(missing.length?'<ul class="completion-strip__missing" aria-label="قدم‌های باقی‌مانده">'+missing.map(x=>'<li>'+(x.id==='slug'||x.id==='lslug'?'<button type="button" class="textlink" data-ready-slug>انتخاب نام و آدرس صفحه</button>':'<a href="'+esc(RI.routeUrl(x.route,{step:x.step,tab:x.tab,anchor:x.anchor}))+'" data-go="'+x.route+'"'+(x.step?' data-step="'+x.step+'"':'')+(x.tab?' data-tab="'+x.tab+'"':'')+'>'+esc(x.label)+'</a>')+'</li>').join('')+'</ul>':'')+'</div>';};
 RI.on('change',()=>{document.querySelectorAll('[data-ready-kind]').forEach(el=>{el.outerHTML=RI.completionStrip(el.dataset.readyKind);});});
 RI.delegate(document,'click','[data-ready-slug]',()=>{let busy=false;const modal=RI.modal({title:'نام و آدرس صفحه',body:'<div class="field"><label class="field__label" for="ready-slug">نام صفحه <span class="field__req">پایهٔ انتشار</span></label><input class="input" id="ready-slug" dir="ltr" maxlength="24" value="'+esc(RI.C().slug)+'"><p class="field__hint">حروف کوچک انگلیسی، عدد و خط تیره؛ ۳ تا ۲۴ نویسه</p><p role="alert" id="ready-slug-error"></p></div>',actions:[{label:'انصراف',kind:'ghost'},{label:'بررسی و انتخاب',kind:'primary',keepOpen:true,onClick:async()=>{if(busy)return;const value=modal.body.querySelector('#ready-slug').value.trim(),status=RI.slugCheck(value),error=modal.body.querySelector('#ready-slug-error');if(status.state!=='ok'){error.textContent=status.msg;return;}busy=true;try{const result=await RI.dashboardRequest('slug?value='+encodeURIComponent(value));if(!result.available){error.textContent='این نام قبلاً انتخاب شده است؛ نام دیگری بنویس.';return;}RI.C().slug=value;RI.touch('slug');modal.close();RI.toast('نام صفحه انتخاب شد؛ برای رزرو نهایی تغییرات را ذخیره کن');}catch(e){error.textContent=e.message;}finally{busy=false;}}}]});});
 RI.startInbox=()=>{
  let timer,stopped=false,seen=new Set(),initial=true,busy=false;
  const poll=async()=>{if(stopped||busy)return;clearTimeout(timer);if(document.hidden){timer=setTimeout(poll,60000);return;}busy=true;try{const inbox=await RI.dashboardRequest('notifications'+(initial?'?updates=1':''));if(stopped)return;RI.inbox=inbox;RI.emit('inbox');for(const item of inbox.rows){if(!initial&&!seen.has(item.id)&&!item.read_at&&inbox.preferences[item.kind]!==false)RI.toast(item.title,{kind:'info'});seen.add(item.id);}initial=false;}catch{}finally{busy=false;if(!stopped)timer=setTimeout(poll,60000);}};
  const visible=()=>{if(!document.hidden)void poll();};document.addEventListener('visibilitychange',visible);
  void poll();window.addEventListener('pagehide',()=>{stopped=true;clearTimeout(timer);document.removeEventListener('visibilitychange',visible);},{once:true});
 };
})();
